        <app-stat-tile label="Off duty" [value]="vm.offDutyCount()" note="injured or missing">
          <ng-icon name="lucideTriangleAlert" />
        </app-stat-tile>
      </div>

      <section class="flex flex-col gap-4" aria-labelledby="top-heroes-heading">
